    # Every horizontal or vertical run of at least two colored cells is a
    # stroke. Fill its internal background gaps, but don't extend beyond it.
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
