    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    ink = next(v for v in counts if v not in (background, 2))
    out = [row[:] for row in grid]

    # Label original 4-connected ink components. Color the gap between
    # collinear marks only when they belong to distinct components.
    component = [[-1] * w for _ in range(h)]
    component_id = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != ink or component[r][c] != -1:
                continue
            component[r][c] = component_id
            q = deque([(r, c)])
            while q:
                rr, cc = q.popleft()
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == ink and component[nr][nc] == -1):
