    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    ink = next(v for v in counts if v not in (bg, 2))
    out = [row[:] for row in grid]
    # Label original 4-connected foreground components. Convert gaps to 2 only
    # when the aligned endpoints are independent pieces, not one connected bar.
    labels = [[-1] * w for _ in range(h)]
    label = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != ink or labels[r][c] >= 0:
                continue
            labels[r][c] = label
            q = deque([(r, c)])
            while q:
                rr, cc = q.popleft()
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == ink and labels[nr][nc] < 0:
                        labels[nr][nc] = label
                        q.append((nr,nc))
            label += 1
